function berlinNow() {
  const f = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false });
  const p = {}; for (const part of f.formatToParts(new Date())) { if (part.type !== 'literal') p[part.type] = part.value; }
  return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}`;
}
function httpError(item) {
  const j = item && item.json ? item.json : {};
  if (j.error) {
    const e = j.error.error || j.error;
    return (e && (e.message || e.code)) ? (e.message || e.code) : 'Microsoft Graph request failed';
  }
  return '';
}

const input = items[0].json || {};
const message_id = safeText(input.message_id);
const attachment_id = safeText(input.attachment_id);
const telegramChatId = safeText(input.telegramChatId);
if (!message_id || !attachment_id) {
  return [{ json: { __invalid:true, response:'Missing message_id or attachment_id. List attachments first.\nVerification status: Failed', verificationStatus:'Failed' } }];
}
return [{ json: { message_id, attachment_id, telegramChatId, file_name: safeText(input.file_name) } }];

